(3453475, 481886, 66223, '<td valign="top">this is one of the coolest shots i''ve seen in a while.  gives a sense of mystery as to what''s going on inside.  too bad we can''t peer through key holes any more...</td>', 'this is one of the coolest shots i''ve seen in a while.  gives a sense of mystery as to what''s going on inside.  too bad we can''t peer through key holes any more...', '2007-03-12 13:43:34.000000', NULL, 1),
(3453478, 479811, 53316, '<td valign="top">Hm. The circle is small, but I think the depth of focus really helps make it a "key" element. Lovely colors.</td>', 'Hm. The circle is small, but I think the depth of focus really helps make it a "key" element. Lovely colors.', '2007-03-12 13:44:08.000000', NULL, 1);
