INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3454641, 482538, 67152, '<td valign="top">nice high key image - love the white border to add to it just that little bit more.</td>', 'nice high key image - love the white border to add to it just that little bit more.', '2007-03-12 20:04:05.000000', NULL, 1),
(3454650, 481465, 67152, '<td valign="top">these are beautiful flowers and the composition of the photo is very nicely done, but there is something about the lighting that doesn''t work for me</td>', 'these are beautiful flowers and the composition of the photo is very nicely done, but there is something about the lighting that doesn''t work for me', '2007-03-12 20:05:20.000000', NULL, 1),
(3454656, 482794, 67152, '<td valign="top">I really like the circles that this image creates - but the reflection of the camera (and maybe of you too?) detracts.</td>', 'I really like the circles that this image creates - but the reflection of the camera (and maybe of you too?) detracts.', '2007-03-12 20:07:11.000000', NULL, 1),
(3454659, 481653, 67152, '<td valign="top">i like the tones on this, but the vignette around the outside of the image does not work for me - I would have preferred a sharp border around the image instead.  Still, its a good image 7</td>', 'i like the tones on this, but the vignette around the outside of the image does not work for me - I would have preferred a sharp border around the image instead.  Still, its a good image 7', '2007-03-12 20:08:29.000000', NULL, 1),
