(3454670, 480721, 67152, '<td valign="top">neat lighthouse - I like the concept, but the lighting is a tad dark for my taste - especially the trees that frame the image.</td>', 'neat lighthouse - I like the concept, but the lighting is a tad dark for my taste - especially the trees that frame the image.', '2007-03-12 20:10:58.000000', NULL, 1),
(3454674, 481422, 67152, '<td valign="top">this is just a little too creepy for me.  well done, but creepy.. 7</td>', 'this is just a little too creepy for me.  well done, but creepy.. 7', '2007-03-12 20:11:45.000000', NULL, 1),
