(3454692, 482688, 67152, '<td valign="top">Hmm - I know this lighthouse.  I am not a fan of the overtly blue colors on the water, but I like how you framed Ledgelight.  I think it may have been really neat to get a little closer and make the circle a more substantial part of the image.</td>', 'Hmm - I know this lighthouse.  I am not a fan of the overtly blue colors on the water, but I like how you framed Ledgelight.  I think it may have been really neat to get a little closer and make the circle a more substantial part of the image.', '2007-03-12 20:15:58.000000', NULL, 1),
(3454693, 482632, 43774, '<td valign="top">This is interesting! I am not sure what this is or how you got the image inside, unless it is a reflection.</td>', 'This is interesting! I am not sure what this is or how you got the image inside, unless it is a reflection.', '2007-03-12 20:16:05.000000', NULL, 1),
(3454694, 479856, 43774, '<td valign="top">Very cool architecture, great exposure.</td>', 'Very cool architecture, great exposure.', '2007-03-12 20:16:25.000000', NULL, 1),
