(3454699, 482462, 43774, '<td valign="top">Very nice, I might have cropped a bit closer to get rid of the empty space in the upper left where there are no logs.</td>', 'Very nice, I might have cropped a bit closer to get rid of the empty space in the upper left where there are no logs.', '2007-03-12 20:17:18.000000', NULL, 1),
