(3457169, 482606, 3087, '<td valign="top">Nice geometrical abstract created from such an everyday object. Love the sheen, the colours and the composition.</td>', 'Nice geometrical abstract created from such an everyday object. Love the sheen, the colours and the composition.', '2007-03-13 18:18:23.000000', NULL, 1),
(3457171, 482262, 3087, '<td valign="top">Funky! Love the unusually low viewpoint and the great framing. High contrast B/W works so well. Very interesting.</td>', 'Funky! Love the unusually low viewpoint and the great framing. High contrast B/W works so well. Very interesting.', '2007-03-13 18:18:58.000000', NULL, 1),
(3457174, 482470, 3087, '<td valign="top">Gently toned black and white works well. Like the shapes, the texture of the bokeh and the composition.</td>', 'Gently toned black and white works well. Like the shapes, the texture of the bokeh and the composition.', '2007-03-13 18:19:45.000000', NULL, 1),
