(3467372, 481945, 75599, '<td valign="top">beautiful!</td>', 'beautiful!', '2007-03-16 20:01:04.000000', NULL, 1),
(3467377, 480318, 12674, '<td valign="top">Lighting a bit harsh.</td>', 'Lighting a bit harsh.', '2007-03-16 20:02:51.000000', NULL, 1),
(3467386, 482606, 61863, '<td valign="top">Excellent I like the colour and texture in this picture - good work</td>', 'Excellent I like the colour and texture in this picture - good work', '2007-03-16 20:08:51.000000', NULL, 1),
(3467426, 481746, 74059, '<td valign="top">This is pretty cool. Love the blue.</td>', 'This is pretty cool. Love the blue.', '2007-03-16 20:56:08.000000', NULL, 1),
(3467434, 481254, 74059, '<td valign="top">This has a lonely feel to it. I like that. I don''t know how long the tunnel is, but maybe if you had been back even further, the impact would have been stronger.</td>', 'This has a lonely feel to it. I like that. I don''t know how long the tunnel is, but maybe if you had been back even further, the impact would have been stronger.', '2007-03-16 21:02:17.000000', NULL, 1),
(3467435, 482534, 74059, '<td valign="top">I like the arrangement but the image lacks impact.  Maybe if the lighting was different.  Not sure if I can put my finger on it.</td>', 'I like the arrangement but the image lacks impact.  Maybe if the lighting was different.  Not sure if I can put my finger on it.', '2007-03-16 21:03:59.000000', NULL, 1),
(3467440, 482443, 74059, '<td valign="top">I like the brightness of this shot.  And the arrangement is nice.  And that is a perfectly round egg.  Is it real?</td>', 'I like the brightness of this shot.  And the arrangement is nice.  And that is a perfectly round egg.  Is it real?', '2007-03-16 21:05:48.000000', NULL, 1),
(3467446, 482826, 74059, '<td valign="top">Very cute and fun.  Is that a Twister boardgame in the background?</td>', 'Very cute and fun.  Is that a Twister boardgame in the background?', '2007-03-16 21:07:52.000000', NULL, 1),
(3467452, 481064, 74059, '<td valign="top">Great image. And I love what you did with the title.</td>', 'Great image. And I love what you did with the title.', '2007-03-16 21:12:18.000000', NULL, 1),
(3467480, 482659, 66384, '<td valign="top">Love the colors and the abstract design.</td>', 'Love the colors and the abstract design.', '2007-03-16 21:32:12.000000', NULL, 1),
(3467486, 482802, 66384, '<td valign="top">Very nice composition, color, and light.</td>', 'Very nice composition, color, and light.', '2007-03-16 21:37:43.000000', NULL, 1),
(3467494, 482683, 7485, '<td valign="top">Ouch, that''s some halo you''ve got there! Good idea though, could be a very good image with more careful postprocessing.</td>', 'Ouch, that''s some halo you''ve got there! Good idea though, could be a very good image with more careful postprocessing.', '2007-03-16 21:47:23.000000', NULL, 1),
(3467501, 481422, 7485, '<td valign="top">Very original! Freaky too, with the jet black eye sockets.</td>', 'Very original! Freaky too, with the jet black eye sockets.', '2007-03-16 21:50:11.000000', NULL, 1),
(3467502, 482802, 7485, '<td valign="top">Perfect lighting and very elegant composition</td>', 'Perfect lighting and very elegant composition', '2007-03-16 21:52:31.000000', NULL, 1),
(3467513, 481207, 7485, '<td valign="top">Okay, so a spiral is obviously not a circle, but this is still a very good photo with great composition</td>', 'Okay, so a spiral is obviously not a circle, but this is still a very good photo with great composition', '2007-03-16 22:00:01.000000', NULL, 1),
(3467520, 482218, 7485, '<td valign="top">Simple and an original interpretation - 8</td>', 'Simple and an original interpretation - 8', '2007-03-16 22:05:13.000000', NULL, 1),
(3467548, 482798, 7485, '<td valign="top">Haven''t I seen a very similar photo here before? But all the same this is very well done and fits the challenge very well, despite being a spiral rather than a circle. The lighting on the background works very well, providing a much more interesting image than if you''d used a plain background.</td>', 'Haven''t I seen a very similar photo here before? But all the same this is very well done and fits the challenge very well, despite being a spiral rather than a circle. The lighting on the background works very well, providing a much more interesting image than if you''d used a plain background.', '2007-03-16 22:12:26.000000', NULL, 1),
(3467553, 482538, 7485, '<td valign="top">Very well done high-key, but the frame crowds the image</td>', 'Very well done high-key, but the frame crowds the image', '2007-03-16 22:14:21.000000', NULL, 1),
(3467576, 482657, 7485, '<td valign="top">Wonderfully done. The lighting is just perfect, the composition meticulously balanced, and of course there''s that trademark silverfoxx touch of the absurd. I find it slightly distracting that the cardboard ribbon, well, it just looks like cardboard. But it only bothers me because of the contrast with the ring, which is wonderfully mysterious and made of some utterly unknown material (you hair?!)</td>', 'Wonderfully done. The lighting is just perfect, the composition meticulously balanced, and of course there''s that trademark silverfoxx touch of the absurd. I find it slightly distracting that the cardboard ribbon, well, it just looks like cardboard. But it only bothers me because of the contrast with the ring, which is wonderfully mysterious and made of some utterly unknown material (you hair?!)', '2007-03-16 22:31:01.000000', NULL, 1),
(3467577, 482688, 60862, '<td valign="top">Nicely seen!  The colors are a little overdone for me, though.</td>', 'Nicely seen!  The colors are a little overdone for me, though.', '2007-03-16 22:32:47.000000', NULL, 1),
(3467579, 482703, 66192, '<td valign="top">My Favorite of the challenge!~<br/>I love how the little one is looking over to see if she is doing it right. Good luck</td>', 'My Favorite of the challenge!~I love how the little one is looking over to see if she is doing it right. Good luck', '2007-03-16 22:33:37.000000', NULL, 1),
(3467580, 480712, 60862, '<td valign="top">The idea is nice, as is the selective desat.  But the composition, with the ear dead center, feels too documentary as opposed to dramatic.</td>', 'The idea is nice, as is the selective desat.  But the composition, with the ear dead center, feels too documentary as opposed to dramatic.', '2007-03-16 22:33:40.000000', NULL, 1),
