(3470077, 482475, 41337, '<td valign="top">There''s a warping feel to this as if the subject has gotten pulled into this composition by the forces of these shapes. Would be interesting to see what else you come up with exploring other shapes.</td>', 'There''s a warping feel to this as if the subject has gotten pulled into this composition by the forces of these shapes. Would be interesting to see what else you come up with exploring other shapes.', '2007-03-18 14:25:20.000000', NULL, 1),
(3470084, 482526, 41337, '<td valign="top">Not crazy about that background but the bubbles are very nice.</td>', 'Not crazy about that background but the bubbles are very nice.', '2007-03-18 14:30:12.000000', NULL, 1),
(3470087, 482153, 74534, '<td valign="top">Very good composition, superb colors and good idea with the long shutter speed. A good border would make this one a fantastic image.</td>', 'Very good composition, superb colors and good idea with the long shutter speed. A good border would make this one a fantastic image.', '2007-03-18 14:30:59.000000', NULL, 1),
(3470088, 482208, 74534, '<td valign="top">Very original for this challenge! I like this a lot.... Just seems a bit over-sharpened.</td>', 'Very original for this challenge! I like this a lot.... Just seems a bit over-sharpened.', '2007-03-18 14:31:04.000000', NULL, 1),
(3470090, 482131, 74534, '<td valign="top">Excellent photo. I like the color tone. I also like the square crop. Hmmm... interesting subject placement, SLIGHTLY off-centered... Yep, very good. Very curious as to what the location is.</td>', 'Excellent photo. I like the color tone. I also like the square crop. Hmmm... interesting subject placement, SLIGHTLY off-centered... Yep, very good. Very curious as to what the location is.', '2007-03-18 14:31:10.000000', NULL, 1),
(3470091, 480952, 74534, '<td valign="top">Excellent lighting, and I like the DOF a lot.</td>', 'Excellent lighting, and I like the DOF a lot.', '2007-03-18 14:32:18.000000', NULL, 1),
(3470093, 482262, 74534, '<td valign="top">Very good B&amp;W, though some loss of detail in the buildings in the back. Very nice composition.</td>', 'Very good B&W, though some loss of detail in the buildings in the back. Very nice composition.', '2007-03-18 14:32:27.000000', NULL, 1),
(3470094, 482705, 74534, '<td valign="top">Nice pic, I like the colors and the reflection a lot. Just makes me wonder of there''s something up those stairs that I''d like to see.</td>', 'Nice pic, I like the colors and the reflection a lot. Just makes me wonder of there''s something up those stairs that I''d like to see.', '2007-03-18 14:32:54.000000', NULL, 1),
(3470095, 481928, 74534, '<td valign="top">Very abstract - but cool idea! Makes you stop and look at it for a while. Yep, this is good!</td>', 'Very abstract - but cool idea! Makes you stop and look at it for a while. Yep, this is good!', '2007-03-18 14:33:09.000000', NULL, 1),
(3470096, 481847, 74534, '<td valign="top">Uh, nice. Hope you didn''t hurt yourself. Good contrast - blue sea and sky / harsh barbed wire.</td>', 'Uh, nice. Hope you didn''t hurt yourself. Good contrast - blue sea and sky / harsh barbed wire.', '2007-03-18 14:33:13.000000', NULL, 1),
(3470097, 481438, 74534, '<td valign="top">Wow... great. One of the more original interpretations of the challenge. Have you tried a black border with a thin orange line inside?</td>', 'Wow... great. One of the more original interpretations of the challenge. Have you tried a black border with a thin orange line inside?', '2007-03-18 14:33:18.000000', NULL, 1),
(3470099, 482743, 74534, '<td valign="top">Wow... lots of negative space, but it really adds to the delicate look. I like the bit of texture / lighting play in the background, though is seems noisy. This being adv. editing, I think a bit of blur on the background would have worked.</td>', 'Wow... lots of negative space, but it really adds to the delicate look. I like the bit of texture / lighting play in the background, though is seems noisy. This being adv. editing, I think a bit of blur on the background would have worked.', '2007-03-18 14:33:55.000000', NULL, 1),
(3470100, 482822, 74534, '<td valign="top">Definitely original - interesting color tone choice. The more I look at it, the more I like it, bumping up. Would have been nice to discern a bit more of what''s going on on the background.</td>', 'Definitely original - interesting color tone choice. The more I look at it, the more I like it, bumping up. Would have been nice to discern a bit more of what''s going on on the background.', '2007-03-18 14:34:09.000000', NULL, 1),
